// Simulación en Node de la propagación de eventos del navegador (captura y burbuja).
// El navegador no expone `document` en Node, así que se modela un árbol mínimo
// con la misma forma que `addEventListener`/`dispatchEvent` reales.
class FakeElement {
  constructor(name, parent = null) {
    this.name = name;
    this.parent = parent;
    this.listeners = [];
  }
  addEventListener(type, handler, useCapture = false) {
    this.listeners.push({ type, handler, useCapture });
  }
  dispatch(type) {
    const path = [];
    for (let node = this; node; node = node.parent) path.unshift(node);
    const event = { type, target: this, currentTarget: null, stopped: false,
      stopPropagation() { this.stopped = true; } };
    for (const node of path) {
      if (event.stopped) break;
      event.currentTarget = node;
      for (const l of node.listeners) if (l.type === type && l.useCapture) l.handler(event);
    }
    for (const node of [...path].reverse()) {
      if (event.stopped) break;
      event.currentTarget = node;
      for (const l of node.listeners) if (l.type === type && !l.useCapture) l.handler(event);
    }
  }
}

const list = new FakeElement('ul');
const item = new FakeElement('li', list);

list.addEventListener('click', () => console.log('captura en ul'), true);
list.addEventListener('click', (e) => console.log('delegado: click en', e.target.name));
item.addEventListener('click', () => console.log('burbuja en li'));

item.dispatch('click');
